RMAX = 1.0
BG = 0.02
SEG = 2000
ENT_AMP = 0.1
ARMS5 = ["f4wA", "f4ng", "f4tw", "cutwA", "cutng25"]
PAIRS2 = ["Ti", "Tr"]
B36 = list(range(3449, 3465))
