    floL = float(np.mean([r["L"] for r in rows]))
    floR = float(np.mean([r["R"] for r in rows]))
    key = f"{bk}|{pk}|{arm}"
    assert floL == PREV["arms"][key]["floL"], ("CERT-FLO floL", key)
